166	void sram_load_elf(const char *filename) {
167	  FILE *f = std::fopen(filename, "rb");
168	  if (!f) {
169	    std::fprintf(stderr, "[SRAM Backdoor] Failed to open ELF file: %s\n",
170	                 filename);
171	    return;
172	  }
173	
174	  Elf32_Ehdr ehdr;
175	  if (std::fread(&ehdr, sizeof(ehdr), 1, f) != 1) {
176	    std::fprintf(stderr, "[SRAM Backdoor] Failed to read ELF header: %s\n",
177	                 filename);
178	    std::fclose(f);
179	    return;
180	  }
181	
182	  // Check ELF magic
183	  if (std::memcmp(ehdr.e_ident, "\x7f\x45\x4c\x46", 4) != 0) {
184	    std::fprintf(stderr, "[SRAM Backdoor] Invalid ELF magic: %s\n", filename);
185	    std::fclose(f);
186	    return;
187	  }
188	
189	  std::fseek(f, ehdr.e_phoff, SEEK_SET);
190	  std::vector<Elf32_Phdr> phdrs(ehdr.e_phnum);
191	  if (std::fread(phdrs.data(), sizeof(Elf32_Phdr), ehdr.e_phnum, f) !=
192	      ehdr.e_phnum) {
193	    std::fprintf(stderr, "[SRAM Backdoor] Failed to read program headers: %s\n",
194	                 filename);
195	    std::fclose(f);
196	    return;
197	  }
198	
199	  for (const auto &phdr : phdrs) {
200	    if (phdr.p_type == PT_LOAD && phdr.p_filesz > 0) {
201	      std::vector<uint8_t> buffer(phdr.p_filesz);
202	      std::fseek(f, phdr.p_offset, SEEK_SET);
203	      if (std::fread(buffer.data(), 1, phdr.p_filesz, f) != phdr.p_filesz) {
204	        std::fprintf(stderr,
205	                     "[SRAM Backdoor] Failed to read segment data: %s\n",
206	                     filename);
207	        continue;
208	      }
209	
210	      SramBackdoorLoad(phdr.p_paddr, buffer.data(), buffer.size());
211	    }
212	  }
213	
214	  std::fclose(f);
215	}
